/* eslint-disable @typescript-eslint/naming-convention */
import { Component, OnInit } from '@angular/core';
import { ActivatedRoute, Router } from '@angular/router';
import { AccountService } from '../../../../data/service/auth/account.service';
import { Urls } from '../../../../core/common/Urls';
import { SharedIonic } from '../../../../core/common/SharedIonic';
import { OrderService } from '../../../../data/service/order/order.service';
import { LoadingController, ToastController } from '@ionic/angular';
import { AccountResponseResult, IAccountResponseResult } from '../../../../data/model/account/IAccountResponseResult';
import { GResponse } from '../../../../core/common/GResponse';
import { CourseService } from '../../../../data/service/course/course.service';
import { FormBuilder, FormGroup, Validators } from '@angular/forms';
import { RegisterModel } from '../../../../data/model/account/RegisterModel';
// import { ReCaptchaV3Service } from 'ngx-captcha';
import { GAccount } from '../../../../core/common/GAccount';

@Component({
  selector: 'app-external',
  templateUrl: './external.component.html',
  styleUrls: ['./external.component.scss']
})
export class ExternalComponent implements OnInit {

  isRegister = false;
  registerForm: FormGroup;
  inputType = 'password';
  isShow = true;
  submitting = false;
  googleSessionExpired = false;

  constructor(
    private activatedRoute: ActivatedRoute,
    private router: Router,
    private accountService: AccountService,
    public toastController: ToastController,
    public loadingController: LoadingController,
    private courseService: CourseService,
    // private reCaptchaV3Service: ReCaptchaV3Service,
    private fb: FormBuilder,
    private orderService: OrderService
  ) { }

  ngOnInit(): void {


    this.registerForm = this.fb.group({
      phoneNumber: ['', [Validators.required, Validators.min(1000000000), Validators.minLength(10), Validators.maxLength(15)]],
      email: ['', [Validators.required, Validators.email]],
      password: ['', [Validators.required, Validators.minLength(3), Validators.maxLength(100)]],
      name: ['', [Validators.required, Validators.maxLength(50)]],
      family: ['', [Validators.required, Validators.maxLength(100)]],
      inviteId: ['', []]
      // address: ['', [Validators.required, Validators.maxLength(1000)]]
    });

    SharedIonic.loading(this.loadingController);

    GAccount.SignOut();

    this.activatedRoute.queryParams.subscribe(query => {

      const Admin = query.Admin;
      const Buyer = query.Buyer;
      const Seller = query.Seller;
      const SuperAdmin = query.SuperAdmin;
      const Teacher = query.Teacher;
      const token = query.token;

      const Email = query.email;
      const firstName = query.firstName;
      const lastname = query.lastname;

      if (token !== undefined) {

        const roles = new Map<string, boolean>();

        if (Admin !== undefined) {

          roles.set('Admin', Admin === 'True' ? true : false);
        }
        if (Buyer !== undefined) {

          roles.set('Buyer', Buyer === 'True' ? true : false);
        }
        if (Seller !== undefined) {

          roles.set('Seller', Seller === 'True' ? true : false);
        }
        if (SuperAdmin !== undefined) {

          roles.set('SuperAdmin', SuperAdmin === 'True' ? true : false);
        }
        if (Teacher !== undefined) {

          roles.set('Teacher', Teacher === 'True' ? true : false);
        }

        const res: IAccountResponseResult = new AccountResponseResult(token, roles);

        AccountService.TokenRolesInit2(res);
        this.afterLogin();
        SharedIonic.dismissLoading(this.loadingController);
        SharedIonic.toast(this.toastController, 'با موفقیت وارد شدید');

        this.loginReturnUrl();

      } else {

        if (Email === undefined) {

          SharedIonic.dismissLoading(this.loadingController);
          this.router.navigateByUrl(Urls.HomeUrl);

        } else {

          let ignoreFirstName = false;
          let ignoreLastName = false;

          if (firstName === undefined) {
            ignoreFirstName = true;
          }
          if (lastname === undefined) {
            ignoreLastName = true;
          }

          this.registerForm.setValue({
            phoneNumber: '',
            email: Email,
            password: '',
            name: ignoreFirstName ? '' : firstName,
            family: ignoreLastName ? '' : lastname,
            inviteId: ''
          });

          this.isRegister = true;
          SharedIonic.dismissLoading(this.loadingController);
        }
      }

    });
  }

  togglePasswordText() {

    this.isShow = false;
    this.inputType = 'text';
  }

  toggleTextPassword() {

    this.isShow = true;
    this.inputType = 'password';
  }

  Register(): void {
    if (!this.registerForm.valid || this.submitting || this.googleSessionExpired) { return; }
    const value = this.registerForm.getRawValue();
    const invitation = Number(value.inviteId);
    const inviteId = Number.isInteger(invitation) && invitation > 0 ? invitation : 0;
    this.submitting = true;
    SharedIonic.loading(this.loadingController);
    this.accountService.ExternalRegister(new RegisterModel(
      String(value.phoneNumber), value.password, value.email.trim(), value.name, value.family, '', inviteId
    )).subscribe({
      next: result => {
        this.submitting = false;
        SharedIonic.dismissLoading(this.loadingController);
        AccountService.TokenRolesInit(result, value.email.trim());
        GResponse.MyCourseIds = [];
        GResponse.setCartCoursesCount(0);
        this.RegisterStatus(200);
      },
      error: () => {
        this.submitting = false;
        SharedIonic.dismissLoading(this.loadingController);
        this.RegisterStatus(AccountService.ErrorState, AccountService.ErrorMessage);
      }
    });
  }

  async RegisterStatus(code: number, responsMsg: any = '') {

    if (responsMsg?.code === 'external_registration_required' || responsMsg?.code === 'external_identity_mismatch') {
      this.googleSessionExpired = true;
      SharedIonic.toast(this.toastController, 'اعتبار ورود گوگل پایان یافته یا با این ایمیل مطابقت ندارد؛ دوباره با گوگل وارد شوید.');
      return;
    }
    if (responsMsg?.code === 'admin_password_required') {
      SharedIonic.toast(this.toastController, 'برای حساب ادمین، رمز عبور و سپس رمز دوم را وارد کنید.');
      void this.router.navigateByUrl(Urls.AccountUrl);
      return;
    }
    let msg = 'خطایی رخ داده';

    if (code === 200) {

      let returnUrl = '/';

      for (let i = 0; i < localStorage.length; i++) {
        if (localStorage.key(i) === 'returnUrl') {
          returnUrl = localStorage.getItem('returnUrl');
          localStorage.removeItem('returnUrl');
        }
      }

      msg = 'عضویت با موفقیت انجام شد';
      SharedIonic.toast(this.toastController, msg);
      this.router.navigateByUrl(returnUrl);
      return;

    } else if (code === 423) {
      msg = 'با پشتیبانی تماس بگیرید';
    } else if (code === 404) {
      msg = 'کاربر یافت نشد';
    } else if (code === 400) {
      if (responsMsg === 'User LockedOut') {
        msg = 'اکانت شما به مدت 1 ساعت مسدود شده است';
      } else if (responsMsg === 'User Dose not Exist') {
        msg = 'ایمیل یا رمز عبور نامعتبر است';
      } else if (responsMsg === 'User Exist') {
        msg = 'کاربر با این ایمیل وجود دارد';
      } else if (responsMsg === 'Bot Detected!') {
        msg = 'شما ربات شناخته شدید';
      } else if (responsMsg === 'Not Created') {
        msg = 'اکانت شما ساخته نشد';
      } else {
        msg = 'ایمیل یا رمز عبور نامعتبر است';
      }
    } else if (code === 406) {
      msg = 'ایمیل یا رمز عبور نامعتبر است';
    } else if (code === 0) {
      return;
    }

    SharedIonic.toast(this.toastController, msg);
  }

  async afterLogin() {

    this.orderService.GetUserCart().subscribe(
      res => {
        if (res.status === GResponse.SuccessStatus) {
          if (res.data.courses == null) {
            GResponse.setCartCoursesCount(0);
          } else {
            GResponse.setCartCoursesCount(res.data.courses.length);
          }
        } else {
          GResponse.setCartCoursesCount(0);
        }
      }
    );

    this.courseService.GetUserCoursesId().subscribe(
      res => {
        if (res.status === GResponse.SuccessStatus) {
          GResponse.MyCourseIds = res.data;
        } else {
          GResponse.MyCourseIds = [];
        }
      }
    );
  }

  async loginReturnUrl() {

    let returnUrl = '/';

    for (let i = 0; i < localStorage.length; i++) {
      if (localStorage.key(i) === 'returnUrl') {
        returnUrl = localStorage.getItem('returnUrl');
        localStorage.removeItem('returnUrl');
      }
    }

    this.router.navigateByUrl(returnUrl);
  }
}
